// LSD radix sort for non-negative integers (base 10).
void radixSort(vector<int>& a) {
    if (a.empty()) return;
    int mx = *max_element(a.begin(), a.end());
    for (int exp = 1; mx / exp > 0; exp *= 10) {
        vector<vector<int>> buckets(10);
        for (int x : a) buckets[(x / exp) % 10].push_back(x);   // stable
        a.clear();
        for (auto& b : buckets)
            for (int x : b) a.push_back(x);
    }
}

class Solution {
public:
    int maximumGap(vector<int>& a) {
        int n = a.size();
        if (n < 2) return 0;
        int mx = *max_element(a.begin(), a.end());
        vector<int> buf(n);
        for (long long exp = 1; mx / exp > 0; exp *= 10) {
            vector<int> cnt(10, 0);
            for (int x : a) cnt[(x / exp) % 10]++;
            for (int i = 1; i < 10; i++) cnt[i] += cnt[i - 1];
            for (int i = n - 1; i >= 0; i--) buf[--cnt[(a[i] / exp) % 10]] = a[i];
            a = buf;
        }
        int gap = 0;
        for (int i = 1; i < n; i++) gap = max(gap, a[i] - a[i - 1]);
        return gap;
    }
};

class Solution:
    def maximumGap(self, a: list[int]) -> int:
        n = len(a)
        if n < 2:
            return 0
        mx = max(a)
        exp = 1
        while mx // exp > 0:
            cnt = [0] * 10
            for x in a:
                cnt[(x // exp) % 10] += 1
            for i in range(1, 10):
                cnt[i] += cnt[i - 1]
            buf = [0] * n
            for x in reversed(a):
                d = (x // exp) % 10
                cnt[d] -= 1
                buf[cnt[d]] = x
            a = buf
            exp *= 10
        return max(a[i] - a[i - 1] for i in range(1, n))

class Solution {
public:
    vector<int> sortArray(vector<int>& a) {
        if (a.empty()) return a;
        int mn = *min_element(a.begin(), a.end());
        for (int& x : a) x -= mn;
        int mx = *max_element(a.begin(), a.end());
        int n = a.size();
        vector<int> buf(n);
        for (long long exp = 1; mx / exp > 0; exp *= 10) {
            vector<int> cnt(10, 0);
            for (int x : a) cnt[(x / exp) % 10]++;
            for (int i = 1; i < 10; i++) cnt[i] += cnt[i - 1];
            for (int i = n - 1; i >= 0; i--) buf[--cnt[(a[i] / exp) % 10]] = a[i];
            a = buf;
        }
        for (int& x : a) x += mn;
        return a;
    }
};

class Solution:
    def sortArray(self, a: list[int]) -> list[int]:
        if not a:
            return a
        mn = min(a)
        a = [x - mn for x in a]
        mx = max(a)
        exp = 1
        while mx // exp > 0:
            cnt = [0] * 10
            for x in a:
                cnt[(x // exp) % 10] += 1
            for i in range(1, 10):
                cnt[i] += cnt[i - 1]
            buf = [0] * len(a)
            for x in reversed(a):
                d = (x // exp) % 10
                cnt[d] -= 1
                buf[cnt[d]] = x
            a = buf
            exp *= 10
        return [x + mn for x in a]

class Solution {
public:
    vector<int> smallestTrimmedNumbers(vector<string>& nums, vector<vector<int>>& queries) {
        int n = nums.size(), L = nums[0].size();
        vector<int> res;
        for (auto& q : queries) {
            int k = q[0], trim = q[1];
            vector<int> idx(n);
            for (int i = 0; i < n; i++) idx[i] = i;
            for (int pos = L - 1; pos >= L - trim; pos--) {
                vector<int> cnt(10, 0), out(n);
                for (int i : idx) cnt[nums[i][pos] - '0']++;
                for (int d = 1; d < 10; d++) cnt[d] += cnt[d - 1];
                for (int i = n - 1; i >= 0; i--) { int d = nums[idx[i]][pos] - '0'; out[--cnt[d]] = idx[i]; }
                idx = out;
            }
            res.push_back(idx[k - 1]);
        }
        return res;
    }
};

class Solution:
    def smallestTrimmedNumbers(self, nums, queries):
        n, L = len(nums), len(nums[0])
        res = []
        for k, trim in queries:
            idx = list(range(n))
            for pos in range(L - 1, L - trim - 1, -1):
                cnt = [0] * 10
                for i in idx:
                    cnt[ord(nums[i][pos]) - 48] += 1
                for d in range(1, 10):
                    cnt[d] += cnt[d - 1]
                out = [0] * n
                for i in reversed(idx):
                    d = ord(nums[i][pos]) - 48
                    cnt[d] -= 1
                    out[cnt[d]] = i
                idx = out
            res.append(idx[k - 1])
        return res

class Solution {
public:
    vector<int> sortByBits(vector<int>& a) {
        sort(a.begin(), a.end(), [](int x, int y){
            int bx = __builtin_popcount(x), by = __builtin_popcount(y);
            return bx != by ? bx < by : x < y;
        });
        return a;
    }
};

class Solution:
    def sortByBits(self, a: list[int]) -> list[int]:
        return sorted(a, key=lambda x: (bin(x).count('1'), x))

class Solution {
public:
    string largestNumber(vector<int>& nums) {
        vector<string> s;
        for (int x : nums) s.push_back(to_string(x));
        sort(s.begin(), s.end(), [](const string& a, const string& b){ return a + b > b + a; });
        if (s[0] == "0") return "0";
        string res;
        for (auto& x : s) res += x;
        return res;
    }
};
